namespace ArgentSea.Orleans;
public sealed class ShardKeyNotFoundException : Exception {   // derives from System.Exception, NOT ApplicationException like the ArgentSea core exceptions
  ShardKeyNotFoundException();                                       // "The Orleans Grain cannot be serialize/deserialzied because the ShardKey attribute could not be found. This attribute is needed to invoke the correct database."
  ShardKeyNotFoundException(string grainType);                       // "The Orleans Grain “{grainType}” cannot be serialize/deserialzied because a ShardKey attribute could not be found. ..."
  ShardKeyNotFoundException(string grainType, Exception innerException); // same grain-type message, wrapping innerException
}
// Unlike most exception types, the single-string constructor takes the GRAIN TYPE, not a free-form message, and there is no message-only constructor; carries no properties beyond the message.
// Raised (always with the grain type) when the grain key marshaller compiles a key/shard delegate for a grain state model that has no shard-key mapping attribute to identify the shard and record columns. It is a configuration defect in the grain state model surfaced on first use of that grain type, not a transient fault.
